// Verify X-Sporta-Signature before anything else.
//
// A webhook URL stops being a secret the moment it appears in a browser
// history, a screenshot or a support ticket. This node is what lets the
// workflow tell the shop from anyone who has seen the URL, and it must run
// FIRST: a workflow that messages a human on an unverified payload is a way
// to make this shop send messages for strangers.
//
// Put the same string that is in api/config.php's n8n_secret into an n8n
// environment variable called SPORTA_N8N_SECRET.
const crypto = require('crypto');
const secret = $env.SPORTA_N8N_SECRET || '';
// AN UNSET SECRET IS NOT A PASS. Falling back to '' computes a valid HMAC with
// an empty key, and the shop's PHP did the same on the other end — so the two
// agreed, the check "passed", and it protected nothing at all. Refuse to run
// rather than accept anything. The shop now also refuses to SEND without one.
if (!secret) throw new Error('SPORTA_N8N_SECRET is not set — refusing to verify');
const raw = $input.first().binary
  ? Buffer.from($input.first().binary.data.data, 'base64').toString('utf8')
  : JSON.stringify($input.first().json);
const got = ($input.first().json.headers || {})['x-sporta-signature'] || '';
const want = crypto.createHmac('sha256', secret).update(raw).digest('hex');
// timingSafeEqual, not ===: comparing a signature byte by byte and stopping
// at the first difference leaks it, one character at a time.
const okLen = got.length === want.length;
const ok = okLen && crypto.timingSafeEqual(Buffer.from(got), Buffer.from(want));
if (!ok) throw new Error('bad signature — refusing');
return [{ json: JSON.parse(raw) }];

